    m = re.match(r'import \{ (.*?) \} from \"@compose/assets\"', line)
    if m:
        print(f'Line {i+1}: @compose/assets: {m.group(1)}')
        symbols = [s.strip() for s in m.group(1).split(',')]
        non_import = '\n'.join(l for l in lines if '@compose/assets' not in l)
